import React, { useMemo } from 'react';
import {
    LineChart,
    Line,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    Legend,
    ResponsiveContainer,
} from 'recharts';
import { useForecastData } from './useForecastData';
import { BEACHES } from './Beaches';
import useTideForecastData from './useTideForecastData';
import { getStoredTideSeries, getTideAtTime } from './tideUtils';

const ForecastChart = ({ selectedBeach, data }) => {
    // Get beach coordinates for API call
    const beach = useMemo(() => 
        BEACHES.find(b => b.name === selectedBeach),
        [selectedBeach]
    );

    const lat = beach?.lat || 32.87;
    const lon = beach?.lon || -117.26;

    // Fetch real forecast data from Open-Meteo
    const { forecastData: apiData, loading, error } = useForecastData(lat, lon);

    // Fetch tide forecast series via reusable hook
    const { tideRows, tideStation } = useTideForecastData(lat, lon);

    // Generate 48-hour forecast data (fallback if API fails)
    const fallbackData = useMemo(() => {
        const now = new Date();
        const currentHour = now.getHours();
        const forecast = [];

        // Simulate 48-hour forecast
        for (let i = 0; i < 48; i++) {
            const hour = (currentHour + i) % 24;
            const isTonight = i < (24 - currentHour);
            const dayLabel = isTonight ? 'Today' : 'Tomorrow';
            const date = new Date(now);
            date.setMinutes(0, 0, 0);
            date.setHours(currentHour + i);

            // Simulate wave height (feet) - ranges 2-8 ft typically
            const baseHeight = 4 + Math.sin((hour - 6) * Math.PI / 12) * 2;
            const swellHeight = baseHeight + Math.random() * 0.5;

            // Wind speed (knots) - typically 5-20 knots
            const windKnots = 12 + Math.sin((hour - 10) * Math.PI / 12) * 6 + Math.random() * 2;

            // Water temp (Celsius) - San Diego 16-22C typically
            const waterTemp = 18 + Math.sin((hour - 12) * Math.PI / 12) * 2;

            // Period (seconds) - typically 8-14s
            const period = 10 + Math.sin((hour - 8) * Math.PI / 12) * 2;

            const timeStr = `${(hour % 12 || 12).toString().padStart(2, '0')}:00 ${hour < 12 ? 'AM' : 'PM'}`;

            forecast.push({
                time: timeStr,
                shortTime: `${hour}h`,
                swellHeight: Math.round(swellHeight * 10) / 10,
                wind: Math.round(windKnots),
                waterTemp: Math.round(waterTemp * 10) / 10,
                period: Math.round(period * 10) / 10,
                hour: i,
                day: dayLabel,
                date,
                timestamp: date.getTime(),
            });
        }

        return forecast;
    }, []);

    // Use real API data if available, otherwise fallback to simulated data
    const baseForecastData = apiData || fallbackData;

    const forecastData = useMemo(() => {
        const mergedTideRows = tideRows.length ? tideRows : getStoredTideSeries();
        if (!mergedTideRows.length) return baseForecastData;

        const withTide = baseForecastData.map((entry, index) => {
            const entryTime = Number.isFinite(entry.timestamp)
                ? entry.timestamp
                : Date.now() + (index * 60 * 60 * 1000);
            const tide = getTideAtTime(mergedTideRows, entryTime);

            return {
                ...entry,
                tideLevel: tide?.level ?? null,
                tidePhase: tide?.phase ?? null,
                tideDirection: tide?.direction ?? null,
            };
        });

        const tideLevels = withTide
            .map((entry) => entry.tideLevel)
            .filter((level) => Number.isFinite(level));

        if (!tideLevels.length) return withTide;

        const leftSeriesValues = withTide
            .flatMap((entry) => [entry.swellHeight, entry.period])
            .filter((value) => Number.isFinite(value));

        const leftAxisMax = leftSeriesValues.length ? Math.max(...leftSeriesValues) : 1;
        const tideMin = Math.min(...tideLevels);
        const tideMax = Math.max(...tideLevels);
        const maxAbsTide = Math.max(Math.abs(tideMin), Math.abs(tideMax));
        const tideScaleFactor = maxAbsTide > 0
            ? (leftAxisMax * 0.9) / maxAbsTide
            : 1;

        return withTide.map((entry) => {
            if (!Number.isFinite(entry.tideLevel)) {
                return {
                    ...entry,
                    tideScaled: null,
                };
            }

            const tideScaled = entry.tideLevel * tideScaleFactor;

            return {
                ...entry,
                tideScaled,
            };
        });
    }, [baseForecastData, tideRows]);

    // Tooltip for detailed info
    const CustomTooltip = ({ active, payload }) => {
        if (!active || !payload || !payload[0]) return null;

        const data = payload[0].payload;
        return (
            <div style={{
                backgroundColor: '#111827',
                border: '1px solid #374151',
                borderRadius: '4px',
                padding: '8px',
                color: '#fff',
                fontSize: '12px',
            }}>
                <div className='containerDetail color-yellow'>
                    {data.time}
                </div>
                <div className='containerDetail flexContainer'>
                    <div className='flex2Column contentRight' style={{ color: '#42a5f5' }}>
                        🌊 Wave Height:
                    </div>  
                    <div className='flexColumn pl-5 contentLeft'>
                        {data.swellHeight}<span className='copyright'>ft</span>
                    </div>
                </div>
                <div className='containerDetail flexContainer'>
                    <div className='flex2Column contentRight' style={{ color: '#ff7043' }}>
                        💨 Wind: 
                    </div>  
                    <div className='flexColumn pl-5 contentLeft'>                        
                        {Math.round(data.wind * 1.15078)}<span className='copyright'>mph</span>
                    </div>
                </div>
                <div className='containerDetail flexContainer'>
                    <div className='flex2Column contentRight' style={{ color: '#26a69a' }}>
                        🌡️ Water Temp: 
                    </div>  
                    <div className='flexColumn pl-5 contentLeft'>
                        {Math.round((data.waterTemp * 9/5) + 32)}°<span className='copyright'>F</span>
                    </div>
                </div>
                <div className='containerDetail flexContainer'>
                    <div className='flex2Column contentRight' style={{ color: '#ab47bc' }}>
                        ⏱️ Period:
                    </div>  
                    <div className='flexColumn pl-5 contentLeft'>
                        {data.period}s
                    </div>
                </div>
                {Number.isFinite(data.tideLevel) && (
                    <div className='containerDetail flexContainer'>
                        <div className='flex2Column contentRight' style={{ color: '#f4d35e' }}>
                            🌗 Tide:
                        </div>
                        <div className='flexColumn pl-5 contentLeft'>
                            {data.tideLevel}<span className='copyright'>ft</span>
                            {/*data.tidePhase ? ` ${data.tidePhase}` : ''*/}
                            {data.tideDirection ? `${(data.tideDirection === 'falling')?'🔻':'🔺'}` : '❓'}
                        </div>
                    </div>
                )}
            </div>
        );
    };

    return (
        <div className='containerDetail'>
            <div className='containerDetail color-yellow contentLeft size20 p-15 mb-10'>
                📊 48-Hour Forecast {selectedBeach && `@ ${selectedBeach}`}
                {tideStation?.name && (
                    <div style={{ fontSize: '12px', marginLeft: '10px', color: '#f4d35e' }}>
                        🌗 Tide: {tideStation.name} ({tideStation.id})
                    </div>
                )}
                {loading && <div style={{ fontSize: '12px', marginLeft: '10px', color: '#666' }}>⏳ Loading real forecast...</div>}
                {error && <div style={{ fontSize: '12px', marginLeft: '10px', color: '#f44336' }}>⚠️ Using simulated data</div>}
            </div>

            {loading && !apiData ? (
                <div style={{
                    textAlign: 'center',
                    padding: '40px',
                    color: '#999',
                    fontSize: '14px',
                }}>
                    Fetching forecast from Open-Meteo...
                </div>
            ) : (
                <>
                    <ResponsiveContainer width="100%" height={300}>
                <LineChart data={forecastData} margin={{ top: 5, right: 8, left: -10, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#ddd" />
                    <XAxis
                        dataKey="time"
                        tick={{ fontSize: 11 }}
                        interval={3}
                        angle={-45}
                        textAnchor="end"
                        height={60}
                    />
                    <YAxis
                        yAxisId="left"
                        domain={[
                            (dataMin) => {
                                const min = Number.isFinite(dataMin) ? dataMin : 0;
                                return Math.min(0, Math.floor((min - 0.25) * 2) / 2);
                            },
                            (dataMax) => Math.ceil((dataMax || 0) * 1.15),
                        ]}
                        tick={{ fontSize: 11 }}
                    />
                    <YAxis
                        yAxisId="right"
                        orientation="right"
                        width={34}
                        tickMargin={2}
                        label={{ value: '💨 Wind (mph)', angle: 90, position: 'insideRight', style: { fill: '#ff7043' } }}
                        tick={{ fontSize: 11 }}
                    />
                    <YAxis
                        yAxisId="temp"
                        hide={true}
                    />
                    <Tooltip content={<CustomTooltip />} />
                    <Legend />
                    <Line
                        yAxisId="left"
                        type="monotone"
                        dataKey="swellHeight"
                        name="🌊 Swell"
                        stroke="#42a5f5"
                        dot={false}
                        strokeWidth={2}
                    />
                    <Line
                        yAxisId="right"
                        type="monotone"
                        dataKey="wind"
                        name="💨 Wind"
                        stroke="#ff7043"
                        dot={false}
                        strokeWidth={2}
                        //strokeDasharray="5 5"
                    />
                    <Line
                        yAxisId="temp"
                        type="monotone"
                        dataKey="waterTemp"
                        name="🌡️ Water"
                        stroke="#26a69a"
                        dot={false}
                        strokeWidth={2}
                        //strokeDasharray="2 4"
                    />
                    <Line
                        yAxisId="left"
                        type="monotone"
                        dataKey="period"
                        name="⏱️ Period"
                        stroke="#ab47bc"
                        dot={false}
                        strokeWidth={2}
                        //strokeDasharray="1 6"
                    />
                    <Line
                        yAxisId="left"
                        type="monotone"
                        dataKey="tideScaled"
                        name="🌗 Tide"
                        stroke="#f4d35e"
                        dot={false}
                        strokeWidth={2}
                        connectNulls={true}
                    />
                </LineChart>
                    </ResponsiveContainer>

                    <div 
                        className='flexContainer'
                    >
                        {/* Summary stats */}
                        {[
                    {
                        label: '🌊 Swell',
                        value: `${Math.max(...forecastData.map(d => d.swellHeight/2))} ft`,
                        color: '#42a5f5',
                    },
                    {
                        label: '💨 Wind',
                        value: `${Math.round((forecastData.reduce((sum, d) => sum + d.wind, 0)*1.15078) / forecastData.length)} mph`,
                        color: '#ff7043',
                    },
                    {
                        label: '🌡️ Water',
                        value: (() => {
                            const waterTemps = forecastData
                                .map((entry) => entry.waterTemp)
                                .filter((temp) => Number.isFinite(temp));

                            if (!waterTemps.length) return 'N/A';

                            const avgCelsius = waterTemps.reduce((sum, temp) => sum + temp, 0) / waterTemps.length;
                            return `${((avgCelsius * 9 / 5) + 32).toFixed(0)}°F`;
                        })(),
                        color: '#26a69a',
                    },
                    {
                        label: '⏱️ Period',
                        value: `${forecastData[0].period}s`,
                        color: '#ab47bc',
                    },
                    {
                        label: '🌗 Tide',
                        value: (() => {
                            const tideLevels = forecastData
                                .map((entry) => entry.tideLevel)
                                .filter((level) => Number.isFinite(level));

                            if (!tideLevels.length) return 'N/A';

                            const minLevel = Math.min(...tideLevels).toFixed(1);
                            const maxLevel = Math.max(...tideLevels).toFixed(1);
                            return `${minLevel}-${maxLevel} ft`;
                        })(),
                        color: '#f4d35e',
                    },
                        ].map((stat, i) => (
                            <div
                                key={i}
                                style={{
                                    backgroundColor: '#222',
                                    border: `2px solid ${stat.color}`,
                                    borderRadius: '6px',
                                    textAlign: 'center',
                                    fontSize: '12px',
                                }}
                                className='w-120 mr-5'
                            >
                                <div className='containerDetail contentLeft size15 mb-5' style={{ color: stat.color }}>{stat.label}</div>
                                <div className='contentLeft mt--5 pl-5 pb-5' style={{ fontSize: '16px', fontWeight: 'bold', color: stat.color, whiteSpace: 'pre-line' }}>
                                    {stat.value.toString().replace(/-(?!.*-)/, 'ft\n')}
                                </div>
                            </div>
                        ))}
                    </div>
                </>
            )}
        </div>
    );
};

export default ForecastChart;
